contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint val) public {
        c.SetMinSum(val);
        uint afterMinSum = c.MinSum();
        bool reverted;
        try c.SetMinSum(val + 1) { reverted = false; } catch { reverted = true; }
        uint finalMinSum = c.MinSum();
        assert(afterMinSum == val && reverted && finalMinSum == val);
    }
}

