contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint val) public {
        bool reverted;
        try c.SetMinSum(val) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            require(c.MinSum() == val, "first SetMinSum did not set MinSum to argument");

            bool reverted2;
            try c.SetMinSum(val) {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }

            assert(reverted2 || c.MinSum() == val);
        } else {
            assert(true);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint v, uint w) public {
        uint before;
        before = c.MinSum();

        bool r1;
        try c.SetMinSum(v) {
            r1 = false;
        } catch {
            r1 = true;
        }

        uint afterFirst;
        afterFirst = c.MinSum();

        bool r2;
        try c.SetMinSum(w) {
            r2 = false;
        } catch {
            r2 = true;
        }

        uint afterSecond;
        afterSecond = c.MinSum();

        assert((!r1 && afterFirst == v) || (r1 && afterFirst == before));
        assert((!r2 && afterSecond == w) || (r2 && afterSecond == afterFirst));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint val) public payable {
        bool revertedOnce;
        try c.SetMinSum(val) {
            revertedOnce = false;
        } catch {
            revertedOnce = true;
        }
        uint got = c.MinSum();
        if (!revertedOnce) {
            assert(got == val);
        } else {
            assert(got == 0);
        }
        c.Initialized();
        bool revertedTwice;
        try c.SetMinSum(val + 1) {
            revertedTwice = false;
        } catch {
            revertedTwice = true;
        }
        assert(revertedTwice && c.MinSum() == got);
    }

    receive() external payable {}
}

