        try c.Initialized() {} catch { return; }
        bool revertedTwice;
        try c.SetMinSum(val + 1) {
            revertedTwice = false;
        } catch {
            revertedTwice = true;
        }
        assertTrue(revertedTwice && c.MinSum() == got);
