contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint am, uint minSum, uint lockTime) public payable {
        require(address(this).balance >= 0);
        require(msg.value == 0);
        // Setup: set MinSum to a parameter value.
        c.SetMinSum(minSum);
        // Setup: lock some balance with an unlock time in the future.
        c.Put{value: lockTime}(lockTime);

        // Read the caller's holder state through the public getter.
        (uint unlockTime, uint balance) = c.Acc(address(this));

        // Decide whether the precondition for Collect should hold.
        bool precondition = (balance >= minSum) && (balance >= am) && (block.timestamp > unlockTime);

        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (precondition) {
            assert(!reverted);
        } else {
            assert(reverted || am == 0);
        }
    }

    receive() external payable {}
}

