        (uint256 afterUnlock, uint256 afterBalance) = c.Acc(address(this));

        // General rule: Collect succeeds iff balance >= MinSum, balance >= amount, and unlock time passed.
        // On success, balance must decrease by exactly amount; on revert, balance unchanged.
        // (afterUnlock and beforeUnlock are read but not needed for this shape; they could differ only if Put was called.)
        assert(
            reverted
                ? (beforeBalance < _minSum || beforeBalance < _collectAmount || block.timestamp <= beforeUnlock) && afterBalance == beforeBalance
                : (beforeBalance >= _minSum && beforeBalance >= _collectAmount && block.timestamp > beforeUnlock) && afterBalance == beforeBalance - _collectAmount
        );
    }

