contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Make the sender's Ether available to the test.
        (bool sentDeposit, ) = address(this).call{value: putAmount}("");
        require(sentDeposit);

        // Ensure the log file is initialized so Put doesn't revert.
        c.SetLogFile(address(1));

        // Seed the caller's holder entry through Put.
        c.Put{value: putAmount}(lockTime);

        // Observe the state before Collect.
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Move time forward so the unlock time has definitely passed.
        // (via the test contract; cheating time would be invalid, but lockTime is user supplied)
        // Instead, we use lockTime=0 to guarantee the condition block.timestamp > unlockTime.
        // Actually we can't force block.timestamp; but with lockTime=0 the condition is true for any timestamp > 0.
        // We still need a general rule over arbitrary lockTime; the precondition below restricts to lockTime==0.
        require(lockTime == 0);

        uint minSumBefore = c.MinSum();

        // Make the deciding call, observing only whether it reverts.
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }

        (, uint afterBalance) = c.Acc(address(this));

        uint balanceDecreased = beforeBalance > afterBalance ? beforeBalance - afterBalance : 0;

        // General rule: with lockTime=0 and the log already set, Collect succeeds if and only if
        // the holder's balance is at least both MinSum and the requested amount, and on success
        // the holder's balance decreases by exactly the collected amount (assuming the fallback
        // does not reenter; the test contract has no fallback that reenters Collect).
        assert(
            !reverted == (beforeBalance >= minSumBefore && beforeBalance >= collectAmount && block.timestamp > beforeUnlock) &&
            (reverted || balanceDecreased == collectAmount)
        );
    }

    receive() external payable {}
}

